package org.springframework.util.concurrent;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.locks.ReentrantLock;

import org.springframework.lang.Nullable;

/**
 * A SettableListenableFuture is a ListenableFuture whose value can be set
 * via the {@link #set(Object)}, {@link #setException(Throwable)}, or
 * {@link #setFuture(ListenableFuture)} methods.
 *
 * @author Arjen Poutsma
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @since 4.0
 * @param <T> the result type
 */
public class SettableListenableFuture<T> implements ListenableFuture<T> {

	/** Synchronizes access to all fields */
	private final ReentrantLock lock = new ReentrantLock();

	/** The listeners for completion notifications */
	private final Collection<ListenableFutureCallback<? super T>> listeners = new ArrayList<>();

	/** Whether the computation has been completed */
	private boolean completed;

	/** The result of the computation, or {@code null} if none */
	@Nullable
	private T result;

	/** The exception of the computation, or {@code null} if none */
	@Nullable
	private Throwable exception;

	/**
	 * Whether this future has been cancelled.
	 * @see #cancel(boolean)
	 */
	private boolean cancelled;


	@Override
	public void addCallback(ListenableFutureCallback<? super T> callback) {
		addCallback(callback, callback);
	}

	@Override
	public void addCallback(SuccessCallback<? super T> successCallback, FailureCallback failureCallback) {
		this.lock.lock();
		try {
			if (!this.completed) {
				this.listeners.add(new ListenableFutureCallback<T>() {
					@Override
					public void onSuccess(@Nullable T result) {
						successCallback.onSuccess(result);
					}
					@Override
					public void onFailure(Throwable ex) {
						failureCallback.onFailure(ex);
					}
				});
			}
			else if (this.exception != null) {
				failureCallback.onFailure(this.exception);
			}
			else {
				successCallback.onSuccess(this.result);
			}
		}
		finally {
			this.lock.unlock();
		}
	}

	/**
	 * Set the result of this future to the given value.
	 * @param result the result
	 * @return {@code false} if the future was already completed,
	 * {@code true} otherwise
	 */
	public boolean set(@Nullable T result) {
		return internalSet(result, null);
	}

	/**
	 * Set the exception of this future to the given exception.
	 * @param exception the exception
	 * @return {@code false} if the future was already completed,
	 * {@code true} otherwise
	 */
	public boolean setException(Throwable exception) {
		return internalSet(null, exception);
	}

	/**
	 * Internal method for setting the result or exception.
	 * @param result the result, or {@code null}
	 * @param exception the exception, or {@code null}
	 * @return {@code false} if the future was already completed,
	 * {@code true} otherwise
	 */
	private boolean internalSet(@Nullable T result, @Nullable Throwable exception) {
		this.lock.lock();
		try {
			if (this.completed || this.cancelled) {
				return false;
			}
			this.completed = true;
			this.result = result;
			this.exception = exception;
			for (ListenableFutureCallback<? super T> listener : this.listeners) {
				invokeListener(listener);
			}
			return true;
		}
		finally {
			this.lock.unlock();
		}
	}

	/**
	 * Invoke the given listener with the current result or exception.
	 * @param listener the listener to invoke
	 */
	@SuppressWarnings("unchecked")
	private void invokeListener(ListenableFutureCallback<? super T> listener) {
		if (this.exception != null) {
			listener.onFailure(this.exception);
		}
		else {
