package org.springframework.core.task.support;

import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;

import org.springframework.core.task.AsyncListenableTaskExecutor;
import org.springframework.util.concurrent.SettableListenableFuture;
import org.springframework.util.concurrent.ListenableFuture;

/**
 * Adapter that takes an {@link java.util.concurrent.ExecutorService}
 * and exposes a full-fledged {@link org.springframework.core.task.AsyncListenableTaskExecutor}.
 *
 * @author Juergen Hoeller
 * @since 2.0.3
 */
public class TaskExecutorAdapter implements AsyncListenableTaskExecutor {

	private final ExecutorService executor;


	/**
	 * Create a new TaskExecutorAdapter, using the given executor.
	 * @param executor the ExecutorService to use
	 */
	public TaskExecutorAdapter(ExecutorService executor) {
		this.executor = executor;
	}


	@Override
	public void execute(Runnable task) {
		try {
			this.executor.execute(task);
		}
		catch (RejectedExecutionException ex) {
			throw new org.springframework.core.task.TaskRejectedException("Executor did not accept task", ex);
		}
	}

	@Override
	public ListenableFuture<?> submitListenable(Runnable task) {
		SettableListenableFuture<Object> future = new SettableListenableFuture<>();
		try {
			Future<?> result = this.executor.submit(task);
			future.set(result);
		}
		catch (RejectedExecutionException ex) {
			future.setException(ex);
		}
		return future;
	}

	@Override
	public <T> ListenableFuture<T> submitListenable(Callable<T> task) {
		SettableListenableFuture<T> future = new SettableListenableFuture<>();
		try {
			Future<T> result = this.executor.submit(task);
			future.setFuture(result);
		}
		catch (RejectedExecutionException ex) {
			future.setException(ex);
		}
		return future;
	}

	/**
	 * Set the result of the given SettableListenableFuture from the given Future.
	 * This is done in a separate thread to avoid blocking.
	 */
	private <T> void setFutureResult(final Future<T> futureResult, final SettableListenableFuture<T> listenableFuture) {
		listenableFuture.addCallback(new org.springframework.util.concurrent.ListenableFutureCallback<T>() {
			@Override
			public void onSuccess(T result) {
				// No-op for callback on set
			}
			@Override
			public void onFailure(Throwable ex) {
				futureResult.cancel(true);
			}
		});
		execute(() -> {
			try {
				listenableFuture.set(futureResult.get());
			}
			catch (InterruptedException ex) {
				Thread.currentThread().interrupt();
				listenableFuture.setException(ex);
			}
			catch (Exception ex) {
				listenableFuture.setException(ex);
			}
		});
	}

}

